from typing import TypedDict, Unpack

from ...base.client import BaseClient


class TasksSearchKwargs(TypedDict):
    filter_id: str


class TasksSearchUserTagsKwargs(TypedDict):
    cursor: str
    filter_id: str


class TasksMethods(BaseClient):
    """
    Методы группы 'Задачи' из https://im-docs.corp.mail.ru/
    """

    async def tasks_search(
        self,
        keyword: str,
        quick_priorities: [tuple[str, ...], list[str]] = (),
        quick_tags: [tuple[str, ...], list[str]] = (),
        quick_labels: [tuple[str, ...], list[str]] = (),
        page_size: int = 20,
        **kwargs: Unpack[TasksSearchKwargs],
    ):
        """
        Метод для получения списка тегов задач, на которые
        подписан пользователь, отсортированный по частоте использования.
        param filter_id:
        """
        for key, value in kwargs.copy().items():
            if value is None:
                kwargs.pop(key)

        return await self.post(
            "rapi/tasks/search",
            json={
                "reqId": self.getReqId(),
                "aimsid": self.aimsid,
                "params": {
                    "keyword": keyword,
                    "quickFilters": {
                        "priorities": quick_priorities,
                        "tags": quick_tags,
                        "labels": quick_labels,
                    },
                    "pageSize": page_size,
                    **kwargs,
                },
            },
        )

    async def tasks_searchUserTags(
        self,
        keyword: str,
        page_size: int = 20,
        **kwargs: Unpack[TasksSearchUserTagsKwargs],
    ) -> dict:
        r"""
        Метод для поиска тегов из задач, на которые подписан пользователь.
        Список отсортирован по частоте использования.
        Поиск ведется по подстроке.
        :param keyword: Текст для поиска
        param filter_id: ID пользовательского фильтра из /tasks/filters/list. Поиск выполняется только для
        отфильтрованых задач. Фильтр по умолчанию -- все задачи.
        param cursor: Курсор, полученный в ответе на предыдущий запрос \n
        param pageSize: Максимальное количество задач в одном ответе
        """
        for key, value in kwargs.copy().items():
            if value is None:
                kwargs.pop(key)

        return await self.post(
            "rapi/tasks/searchUserTags",
            json={
                "reqId": self.getReqId(),
                "aimsid": self.aimsid,
                "params": {
                    "pageSize": page_size,
                    "keyword": keyword,
                    **kwargs,
                },
            },
        )
